  Rcpp::CharacterVector raw_to_string(Rcpp::RawVector x) {
    char buf[2 * x.length() + 3];
    char* p = buf;

    const char* lookup = \"0123456789abcdef\";

    *p++ = '0';
    *p++ = 'x';

